namespace gui_forms {

// Panel's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/panel.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The panel's border: none, a line, sunken or raised (BorderStyle).
template <typename Declaring>
struct BorderStyleCapability {
    PropertyCell<BorderStyle, BorderStyleCapability<Declaring>> border_style{BorderStyle::none};

    static void assign(BorderStyleCapability& capability, BorderStyle incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.border_style), incoming);
        if (!capability.border_style.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.border_style));
    }
};

// The recipe family the panel paints with: window, panel or card.
template <typename Declaring>
struct VisualRoleCapability {
    PropertyCell<ControlVisualRole, VisualRoleCapability<Declaring>> visual_role{ControlVisualRole::panel};

    static void assign(VisualRoleCapability& capability, ControlVisualRole incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.visual_role), incoming);
        if (!capability.visual_role.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.visual_role));
    }
};

// BorderStyle as a property value; defined beside Panel's table.
template <>
struct PropertyValueTraits<BorderStyle> {
    static PropertyType type();
    static BindingValue to_binding(BorderStyle value);
    static BorderStyle from_binding(const BindingValue& value);
};

// Every Panel capability, in the order the declaring class takes them.
template <typename Declaring>
struct PanelCapabilities : public BorderStyleCapability<Declaring>,
                           public VisualRoleCapability<Declaring> {};

} // namespace gui_forms
